import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
g = data[2:2 + r]
sr, sc, dr, dc = (int(x) for x in data[2 + r:6 + r])
INF = 10 ** 9
dist = [[INF] * c for _ in range(r)]
if g[sr][sc] == '.':
    dist[sr][sc] = 0
changed = True
while changed:
    changed = False
    for i in range(r):
        for j in range(c):
            if g[i][j] != '.':
                continue
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = i + di, j + dj
                if 0 <= a < r and 0 <= b < c and g[a][b] == '.' and dist[a][b] + 1 < dist[i][j]:
                    dist[i][j] = dist[a][b] + 1
                    changed = True
ans = dist[dr][dc] if g[dr][dc] == '.' else INF
print(ans if ans < INF else -1)

